code_examples.text:
when HTTP_REQUEST {
    set in_path [HTTP::path]
    log local0. "debug request: path $in_path"
    switch -glob $in_path {
        "/pool*" {
            set pool [string map {"/pool" ""} $in_path]
            HTTP::respond 200 content "[active_members $pool]:[nodes $pool]"
        }
    }
}
